{#- Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/post-grid.json
    A section with a heading and the posts as cards: a grid, a list of horizontal cards, or a magazine (the first post wide, the rest in a grid). Axes: layout (grid, list, magazine), columns, media, meta (full, short, news), filter mode (none, topics), tone, density.
    Props (p): id, title, posts, labels, action, filter, layout, cols, media, meta, tone, density, landmarkLabel. -#}
{%- set v_id = (p.id ?? null) -%}
{%- set v_title = (p.title ?? null) -%}
{%- set v_posts = (p.posts ?? null) -%}
{%- set v_labels = (p.labels ?? null) -%}
{%- set v_action = (p.action ?? null) -%}
{%- set v_filter = (p.filter ?? null) -%}
{%- set v_layout = (p.layout ?? 'grid') -%}
{%- set v_cols = (p.cols ?? '1-3') -%}
{%- set v_media = (p.media ?? 'image') -%}
{%- set v_meta = (p.meta ?? 'full') -%}
{%- set v_tone = (p.tone ?? 'default') -%}
{%- set v_density = (p.density ?? 'default') -%}
{%- set v_landmarkLabel = (p.landmarkLabel ?? null) -%}
{%- set c_6 -%}
  {%- if ui_t(ui_eq(ui_get(v_filter, ['mode']), 'topics')) %}
    {%- set c_2 -%}
      {%- for v_tab in ui_l(ui_get(v_filter, ['topics'])) %}
        {%- set c_1 -%}
          {{ ui_text(ui_get(v_tab, ['title'])) }}
        {%- endset -%}
        {{ include('blocks/switcher-item.html.twig', {'p': {'active': ui_eq(ui_get(v_tab, ['value']), ui_get(v_filter, ['topic']))}, 'children': c_1}, with_context = false) }}
      {%- endfor %}
    {%- endset -%}
    {{ include('blocks/switcher.html.twig', {'p': {'label': ui_get(v_filter, ['label'])}, 'children': c_2}, with_context = false) }}
  {%- endif %}
  {%- if ui_t(ui_eq(v_layout, 'magazine')) %}
    {%- set c_4 -%}
      {%- for v_p in ui_l(ui_where(v_posts, 'category', ui_get(v_filter, ['topic']))) %}
        {%- set v_i = loop.index0 -%}
        {%- if ui_t(ui_eq(v_i, 0)) %}
          {{ include('blocks/post-card.html.twig', {'p': {'post': v_p, 'labels': v_labels, 'layout': 'horizontal', 'media': v_media, 'meta': v_meta, 'density': v_density}}, with_context = false) }}
        {%- endif %}
      {%- endfor %}
      {%- set c_3 -%}
        {%- for v_p in ui_l(ui_where(v_posts, 'category', ui_get(v_filter, ['topic']))) %}
          {%- set v_i = loop.index0 -%}
          {%- if ui_t(ui_gt(v_i, 0)) %}
            {{ include('blocks/post-card.html.twig', {'p': {'post': v_p, 'labels': v_labels, 'media': v_media, 'meta': v_meta, 'density': v_density}}, with_context = false) }}
          {%- endif %}
        {%- endfor %}
      {%- endset -%}
      {{ include('ui/grid/grid.html.twig', {'p': {'Cols': ui_s(v_cols), 'Class': 'gap-6'}, 'children': c_3}, with_context = false) }}
    {%- endset -%}
    {{ include('ui/stack/stack.html.twig', {'p': {'Gap': '6', 'Align': 'stretch', 'Attrs': ui_attrs(['data-testid', 'items'])}, 'children': c_4}, with_context = false) }}
  {%- else %}
    {%- set c_5 -%}
      {%- for v_p in ui_l(ui_where(v_posts, 'category', ui_get(v_filter, ['topic']))) %}
        {{ include('blocks/post-card.html.twig', {'p': {'post': v_p, 'labels': v_labels, 'layout': (ui_t(ui_eq(v_layout, 'list')) ? 'horizontal' : 'vertical'), 'media': v_media, 'meta': v_meta, 'density': v_density}}, with_context = false) }}
      {%- endfor %}
    {%- endset -%}
    {{ include('ui/grid/grid.html.twig', {'p': {'Cols': ui_s((ui_t(ui_eq(v_layout, 'list')) ? '1' : ui_fit_cols(v_cols, ui_len(ui_where(v_posts, 'category', ui_get(v_filter, ['topic'])))))), 'Class': 'w-full gap-6', 'Attrs': ui_attrs(['data-testid', 'items'])}, 'children': c_5}, with_context = false) }}
  {%- endif %}
{%- endset -%}
{{ include('blocks/section-frame.html.twig', {'p': {'id': v_id, 'title': v_title, 'action': v_action, 'tone': v_tone, 'density': (ui_t(ui_eq(v_density, 'compact')) ? 'compact' : 'default'), 'measure': (ui_t(ui_eq(v_meta, 'news')) ? 'fill' : 'default'), 'className': ui_cnv([(ui_t(ui_eq(v_meta, 'news')) ? 'py-0' : '')]), 'landmarkLabel': v_landmarkLabel}, 'children': c_6}, with_context = false) }}
